import React, { useState, useEffect } from 'react';
import Login from './components/Login';
import Sidebar from './components/Sidebar';
import Tasks from './components/Tasks';
import CalendarView from './components/CalendarView';
import Templates from './components/Templates';
import api from './api';

function App() {
  const [user, setUser] = useState(null);
  const [currentView, setCurrentView] = useState('tasks');
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedTaskView, setSelectedTaskView] = useState('daily');
  const [sidebarOpen, setSidebarOpen] = useState(true);

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (token) {
      // Token exists, set a temporary user object
      // The actual user data will be loaded after login
      setUser({ token });
    }
  }, []);

  const handleLogin = (userData) => {
    setUser(userData);
  };

  const handleLogout = () => {
    api.logout();
    setUser(null);
    setCurrentView('tasks');
  };

  const handleDateSelect = (date, view = 'daily') => {
    setSelectedDate(date);
    setSelectedTaskView(view);
    setCurrentView('tasks');
  };

  const handleViewChange = (view) => {
    setCurrentView(view);
    setSidebarOpen(false);
  };

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="app">
      <Sidebar 
        currentView={currentView} 
        onViewChange={handleViewChange}
        onLogout={handleLogout}
        isOpen={sidebarOpen}
        onToggle={() => setSidebarOpen(!sidebarOpen)}
        user={user}
      />
      <div className={`content ${sidebarOpen ? 'sidebar-open' : ''}`}>
        {currentView === 'tasks' && (
          <Tasks 
            selectedDate={selectedDate} 
            onDateChange={setSelectedDate}
            initialView={selectedTaskView}
          />
        )}
        {currentView === 'calendar' && (
          <CalendarView onDateSelect={handleDateSelect} />
        )}
        {currentView === 'templates' && <Templates />}
      </div>
    </div>
  );
}

export default App;
